<script setup lang="ts">
import { Archive, AudioLines, CalendarClock, CalendarDays, Eye, FileText, Pencil, Send, Sparkles, Trash2 } from '@lucide/vue'
import { assignmentTypeLabels, type ManagedAssignment } from '../../stores/assignmentManagement'
defineProps<{ assignment: ManagedAssignment }>()
defineEmits<{ publish: []; archive: []; remove: [] }>()
const formatter = new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn', { day: '2-digit', month: 'long', year: 'numeric' })
function date(value: string) { return formatter.format(new Date(value)) }
</script>
<template>
  <article class="space-y-4 rounded-3xl border border-line bg-white p-5">
    <header class="flex items-start gap-3"><span class="rounded-2xl bg-violet-50 p-3 text-violet-600"><component :is="assignment.type === 'optional' ? Sparkles : assignment.type === 'listening' ? AudioLines : FileText" :size="22" /></span><div class="min-w-0 flex-1"><div class="mb-3 flex flex-wrap gap-2 text-xs"><span class="rounded-full bg-violet-50 px-3 py-1 text-violet-600">{{ assignmentTypeLabels[assignment.type] }}</span><span class="rounded-full bg-slate-100 px-3 py-1 text-muted">الأسبوع {{ assignment.week }}</span><span class="rounded-full px-3 py-1" :class="assignment.status === 'published' ? 'bg-emerald-50 text-brand' : 'bg-amber-50 text-amber-700'">{{ assignment.status === 'published' ? 'منشور' : 'مجدول' }}</span></div><h3 class="text-base font-bold leading-7">{{ assignment.title }}</h3></div></header>
    <template v-if="assignment.status === 'published'">
      <dl class="grid grid-cols-2 gap-3"><div class="rounded-2xl bg-slate-50 p-3"><dt class="text-xs text-muted">تم النشر</dt><dd class="mt-2 flex items-center gap-2 text-xs font-bold"><CalendarDays :size="14" />{{ date(assignment.publishDate) }}</dd></div><div class="rounded-2xl bg-amber-50 p-3 text-amber-800"><dt class="text-xs">الموعد النهائي</dt><dd class="mt-2 text-xs font-bold">{{ date(assignment.deadline) }}</dd></div></dl>
      <div class="rounded-2xl border border-line p-3"><div class="flex justify-between"><div><p class="text-xs text-muted">التسليمات</p><p class="mt-1 text-lg font-bold" dir="ltr">{{ assignment.submissions }}/{{ assignment.participants }}</p></div><div><p class="text-xs text-muted">نسبة الإنجاز</p><p class="mt-1 text-sm font-bold text-brand">{{ Math.round(assignment.submissions / assignment.participants * 100) }}%</p></div></div><div role="progressbar" aria-label="نسبة التسليمات" :aria-valuenow="assignment.submissions" :aria-valuemin="0" :aria-valuemax="assignment.participants" class="mt-3 h-1.5 overflow-hidden rounded-full bg-brand/10"><div class="h-full rounded-full bg-brand" :style="{ width: `${assignment.submissions / assignment.participants * 100}%` }" /></div></div>
