      <div class="flex items-center gap-3 rounded-2xl border border-amber-200 bg-gradient-to-l from-amber-100 to-amber-50 p-4 text-amber-800"><CalendarClock :size="22" /><div><p class="text-xs">موعد النشر التلقائي</p><p class="mt-1 text-sm font-bold">{{ date(assignment.publishDate) }} - الساعة {{ assignment.publishDate.slice(11,16) }}</p></div></div>
      <dl class="grid grid-cols-2 gap-3"><div class="rounded-2xl bg-slate-50 p-3"><dt class="text-xs text-muted">الموعد النهائي</dt><dd class="mt-2 text-sm font-bold">{{ date(assignment.deadline) }}</dd></div><div class="rounded-2xl bg-slate-50 p-3"><dt class="text-xs text-muted">وزن التكليف</dt><dd class="mt-2 text-sm font-bold">{{ assignment.weight }}%</dd></div></dl>
      <footer class="flex flex-wrap gap-2 border-t border-slate-100 pt-3"><button disabled type="button" title="تعديل الجدولة سيُضاف لاحقًا" class="min-h-10 flex-1 cursor-default! rounded-xl border border-line px-3 text-xs text-slate-600">تعديل موعد النشر</button><button type="button" class="flex min-h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-brand px-3 text-xs font-bold text-white hover:bg-brand-dark" @click="$emit('publish')"><Send :size="14" />نشر الآن</button><button type="button" class="flex min-h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-red-50 px-3 text-xs font-bold text-red-600 hover:bg-red-100" @click="$emit('remove')"><Trash2 :size="14" />حذف التكليف</button></footer>
    </template>
  </article>
</template>
